"""Build the ACCESS machine identification atlas and WHMIS classroom resources."""
from pathlib import Path
from html import escape as E
import csv,hashlib,json,shutil,fitz
R=Path(__file__).resolve().parents[1];W=R.parent/'whmis'
M=json.loads((R/'manifest.json').read_text());D={d['id']:d for d in M['documents']};A=json.loads((R/'atlas.json').read_text());H=json.loads((W/'manifest.json').read_text())
def write(p,s):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
def source(doc,n,prefix=''):
 d=D[doc];p=next(p for p in d['parts'] if p['start']<=n<=p['end']);return prefix+p['file']+f'#page={n-p["start"]+1}'
def credit(doc,n,prefix=''):
 d=D[doc];return f'{E(d["publisher"])}. ({d["publication_year"] or "n.d."}). <em>{E(d["title"])}</em> ({E(d.get("publication") or "publication number not transcribed")}), PDF p. {n}. <a href="{source(doc,n,prefix)}">Full source page</a>. Original illustration reproduced as a crop; labels unchanged.'
CSS='''@font-face{font-family:Plex;src:url('fonts/ibm-plex-sans-latin-400-normal.woff2')}@font-face{font-family:Plex;src:url('fonts/ibm-plex-sans-latin-600-normal.woff2');font-weight:600}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#F7F4F1;color:#1A1512;font:17px/1.6 Plex,Arial,sans-serif}a{color:#a71920;text-underline-offset:3px}h1,h2,h3{line-height:1.15}h1{font-size:clamp(38px,6vw,70px);letter-spacing:-.045em;max-width:850px;margin:22px 0}h2{font-size:clamp(27px,4vw,39px);letter-spacing:-.025em}h3{font-size:21px}.hero{background:#1A1512;color:#fff;border-bottom:8px solid #FFBC00;padding:46px 28px}.hero>div,main{max-width:1240px;margin:auto}.hero p{max-width:760px}.eyebrow{font-size:13px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:#FFBC00}.hero .lead{font-size:22px;color:#e5dbd2}.hero .edition{font-size:13px;color:#d2c7bd}main{padding:26px 24px}.nav{display:flex;gap:12px 22px;flex-wrap:wrap;padding:0 0 24px}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:24px 0}.stat{background:#fff;border-top:4px solid #D2181F;padding:20px}.stat strong{display:block;font-size:32px}.stat span{font-size:14px;color:#625D58}.panel{background:#fff;border:1px solid #ddd3cb;border-radius:8px;padding:26px;margin:26px 0}.panel h2{margin-top:0}.callout{border-left:5px solid #FFBC00;background:#fff8e0;padding:17px 22px;margin:20px 0}.atlas-card{background:#fff;border:1px solid #ded5cd;border-radius:8px;margin:30px 0;overflow:hidden;scroll-margin-top:12px}.card-head{border-top:5px solid #D2181F;padding:22px 26px 12px}.card-head h2{margin:8px 0 10px;font-size:30px}.kicker{font-size:13px;color:#a71920;font-weight:600;letter-spacing:.06em}.scope,.credit,.meta{font-size:13px;color:#625D58}.plate{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:24px;padding:0 26px 24px}.plate.single{display:block}.plate figure{margin:0;min-width:0}.plate img{display:block;width:100%;height:auto;background:white;max-height:720px;object-fit:contain}.plate figcaption{margin-top:14px}.legend{width:100%;border-collapse:collapse;font-size:14px}.legend th{background:#1A1512;color:#fff;text-align:left;padding:10px}.legend td{padding:9px 8px;vertical-align:top;border-bottom:1px solid #dfd6cd}.legend td:first-child{width:56px;color:#a71920;font-weight:600}.legend small{display:block;font-size:12px;color:#625D58}.legend tbody tr:nth-child(even){background:#faf8f5}.searchbox{background:#1A1512;color:#fff;border-radius:8px;padding:22px}.searchbox input{display:block;width:100%;font:inherit;padding:13px;margin:12px 0;border:2px solid #FFBC00;border-radius:5px}.searchbox p{font-size:14px;margin:5px 0}.chips{display:flex;gap:8px;flex-wrap:wrap}.chips a{padding:7px 12px;background:#fff;border:1px solid #d7cdc3;border-radius:4px;font-size:14px}.exercise{padding:18px 0;border-bottom:1px solid #ddd4cc;break-inside:avoid}.exercise h3{margin:0 0 10px}.exercise .skills{font-size:13px;color:#a71920;font-weight:600}.answer-space{height:65px;background:repeating-linear-gradient(to bottom,transparent 0,transparent 30px,#ddd3cb 31px,#ddd3cb 32px)}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:0;list-style:none;counter-reset:step}.steps li{background:#fff;border-bottom:4px solid #FFBC00;padding:18px;counter-increment:step}.steps li:before{content:'0' counter(step);display:block;font-size:29px;font-weight:600;color:#a71920}.symbol-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.symbol{display:grid;grid-template-columns:112px minmax(0,1fr);gap:20px;border:1px solid #ddd3cb;border-radius:8px;padding:20px;background:#fff;break-inside:avoid}.symbol img{width:112px;height:112px;object-fit:contain}.symbol h3{margin:0 0 8px}.symbol p{font-size:15px;margin:0 0 10px}.symbol .links{font-size:12px}.tablewrap{overflow:auto}table.simple{border-collapse:collapse;width:100%;font-size:15px}table.simple th,table.simple td{border:1px solid #d6ccc2;padding:10px;text-align:left;vertical-align:top}table.simple th{background:#eee6dc}.machine-page{display:block;width:100%;max-height:750px;object-fit:contain}.download-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.skip{position:absolute;left:-9999px}.skip:focus{left:12px;top:12px;background:#fff;padding:10px;z-index:9}a:focus-visible,input:focus-visible,button:focus-visible{outline:3px solid #D2181F;outline-offset:4px}p,li,td,a{overflow-wrap:anywhere}[hidden]{display:none!important}.print-only{display:none}@media(max-width:850px){.plate{grid-template-columns:1fr}.symbol-grid{grid-template-columns:1fr}.steps{grid-template-columns:repeat(2,1fr)}.download-grid{grid-template-columns:1fr}}@media(max-width:480px){main{padding:18px 12px}.hero{padding:32px 18px}.hero .lead{font-size:19px}.stats{gap:7px}.stat{padding:12px}.stat strong{font-size:27px}.panel,.card-head{padding:19px}.plate{padding:0 16px 19px}.symbol{grid-template-columns:78px minmax(0,1fr);gap:12px;padding:15px}.symbol img{width:78px;height:78px}.steps{grid-template-columns:1fr}.legend{font-size:13px}}@media print{@page{size:A4;margin:14mm 13mm 16mm}body{background:#fff;font-size:10pt;line-height:1.35}main{padding:0;max-width:none}.hero{padding:18mm 6mm;color:#1A1512;background:white;border-bottom:5pt solid #FFBC00;break-after:page}.hero h1{font-size:43pt}.hero .lead{color:#1A1512;font-size:18pt}.hero .edition,.eyebrow{color:#625D58}.nav,.searchbox,.chips,.skip,.screen-only,.answer-space{display:none}.print-only{display:block}.panel{border:0;border-radius:0;padding:0;margin:0;break-before:page}h2{font-size:23pt}h3{font-size:13pt}.stats{margin:15pt 0}.stats+.panel{break-before:auto}.stat{padding:12pt}.stat strong{font-size:23pt}.stat span{font-size:10pt}.callout{padding:10pt}.steps{grid-template-columns:repeat(2,1fr)}.atlas-card{border:0;border-radius:0;margin:0;break-before:page}.card-head{padding:12pt 0 6pt;border-top:3pt solid #D2181F}.card-head h2{font-size:22pt}.plate{display:block;padding:0}.plate img{max-height:125mm;width:100%;object-fit:contain}.plate.single img{max-height:180mm}.plate figcaption{margin:7pt 0}.scope,.credit,.meta{font-size:8pt}.legend{font-size:9pt;line-height:1.2}.legend th{color:#1A1512;background:#eee6dc;padding:5pt}.legend td{padding:4pt 5pt}.legend small{font-size:8pt}.atlas-card.controls .plate img{max-height:77mm}.atlas-card.controls .legend{font-size:8pt}.atlas-card.controls .legend td{padding:2.5pt 4pt}.atlas-card.controls .legend small{display:none}.symbol-grid{grid-template-columns:1fr;gap:10pt}.symbol{grid-template-columns:70pt 1fr;padding:12pt}.symbol img{width:70pt;height:70pt}.symbol h3{font-size:15pt}.symbol p{font-size:10pt}.symbol .links{font-size:8pt}.symbol:nth-child(6){break-before:page}.exercise{padding:10pt 0}.exercise p{margin:6pt 0}.machine-page{max-height:205mm}.tablewrap{overflow:visible}table.simple{font-size:9pt}table.simple td,table.simple th{padding:6pt}.download-grid{display:block}a{color:#a71920;text-decoration:none}}
'''
for root in [R,W]:
 write(root/'assets/classroom.css',CSS)
 fonts=root/'assets/fonts';fonts.mkdir(exist_ok=True)
 for p in (R.parent/'assets/fonts').iterdir():
  if p.name in ['ibm-plex-sans-latin-400-normal.woff2','ibm-plex-sans-latin-600-normal.woff2'] or p.suffix in ['.txt','.md']:shutil.copyfile(p,fonts/p.name)
def shell(title,lead,body,nav,script=''):
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | ACCESS IS4S</title><link rel="stylesheet" href="assets/classroom.css"></head><body><a class="skip" href="#main">Skip to learning material</a><header class="hero"><div><p class="eyebrow">ACCESS · Indigenous Skills 4 Success</p><h1>{title}</h1><p class="lead">{lead}</p><p class="edition">ASPHALT · CLASSROOM EDITION · 30 OCTOBER 2026</p></div></header><main id="main"><nav class="nav">{nav}</nav>{body}</main>{script}</body></html>'
nav='<a href="index.html">CAT library</a><a href="parts-atlas.pdf">Print the atlas</a><a href="practice.html">Identification practice</a><a href="../whmis/index.html">WHMIS and machine warnings</a><a href="downloads.html">ZIP downloads</a>'
body=f'<div class="stats"><div class="stat"><strong>20</strong><span>Source illustrations</span></div><div class="stat"><strong>{A["component_rows"]}</strong><span>Named components</span></div><div class="stat"><strong>22</strong><span>Searchable publications</span></div></div><section class="panel"><h2>A shared language for the crew</h2><p>A precise part name helps a crew explain an observation, find the right diagram and check understanding. Follow the leader line to the part. Say its name. Read its function. Then check the model and publication before using the information.</p><ol class="steps"><li><strong>Find the machine</strong><br>Record model, serial-number prefix and attachment.</li><li><strong>Find the assembly</strong><br>Use the section title and diagram.</li><li><strong>Follow the callout</strong><br>Match its number, letter or printed label.</li><li><strong>Check the match</strong><br>Confirm model, build and serial range in the source.</li></ol><p class="callout">These selected diagrams teach component identification. For the complete parts list for a training machine, use its serial-specific parts catalogue. The collection includes two complete roller operation manuals; public parts reference guides list selected parts. <a href="coverage.md">See equipment coverage and remaining manual needs</a>.</p><p>Use photographs, pointing, reading aloud and partner check-backs as needed. Learners may bring workplace experience or work entirely from these supplied examples. Local Nation-specific language or knowledge is included only through locally chosen participation.</p></section><div class="searchbox"><label for="part-filter">Find a component, assembly or machine</label><input id="part-filter" type="search" placeholder="Try: auger, pin, roller, heater"><p id="part-status" role="status">20 illustrated sections</p></div><nav class="chips" aria-label="Atlas contents">'+''.join(f'<a href="#{f["id"]}">{E(f["title"])}</a>' for f in A['figures'])+'</nav>'
rows=[]
for i,f in enumerate(A['figures'],1):
 cs=f['components'];cl=' controls' if f['id']=='roller-controls' else '';search=E(' '.join([f['title'],f['scope']]+[c['name'] for c in cs]).lower(),quote=True)
 legend='<table class="legend"><thead><tr><th>Mark</th><th>Component and meaning</th></tr></thead><tbody>'+''.join(f'<tr><td>{E(c["locator"])}</td><td><strong>{E(c["name"])}</strong><small>{E(c["explanation"])}</small></td></tr>' for c in cs)+'</tbody></table>' if cs else '<p class="callout">Read the original table headings and model/serial qualifiers in this complete source page. Open the image or PDF to magnify the small text. Keep each part number with its model and table column.</p>'
 body+=f'<section class="atlas-card{cl}" id="{f["id"]}" data-search="{search}"><div class="card-head"><span class="kicker">FIGURE {i:02d} · {f["document"]} · SOURCE PDF PAGE {f["source_page"]}</span><h2>{E(f["title"])}</h2><p class="scope">{E(f["scope"])}</p></div><div class="plate{(" single" if not cs else "")}"><figure><a href="{f["file"]}" aria-label="Open full-size illustration: {E(f["title"],quote=True)}"><img src="{f["file"]}" alt="{E(f["title"],quote=True)}. Original callouts are reproduced; their names appear in the adjacent legend or source table." width="{f["image_pixels"][0]}" height="{f["image_pixels"][1]}"></a><figcaption class="credit">{credit(f["document"],f["source_page"])}</figcaption></figure>{legend}</div></section>'
 for c in cs:rows.append([f['id'],f['document'],f['source_page'],c['locator'],c['name'],c['explanation'],f['scope'],source(f['document'],f['source_page'])])
body+='<section class="panel"><h2>Build the record for your actual machine</h2><p>Record manufacturer, model, complete product identification/serial number, attachment model, publication number, revision, applicable serial range, diagram group and callout. A similar-looking machine is a starting point for a search; it is not enough to choose a part number.</p><p>Use <a href="https://parts.cat.com/en/catcorp/parts-diagram">Cat Parts Diagrams</a> and the <a href="https://www.cat.com/en_US/support/maintenance/service-manuals.html">Cat service-manual route</a>. Confirm any required account or dealer access through the provider. Keep the applicable operation manual beside the parts catalogue.</p><p><a href="component-register.csv">Download the 89-row component register</a> · <a href="atlas.json">Figure provenance and crop record</a> · <a href="coverage.md">Coverage by machine family</a></p></section>'
js=r'''<script>(()=>{const q=document.querySelector('#part-filter'),s=document.querySelector('#part-status');q.addEventListener('input',()=>{const words=q.value.trim().toLowerCase().split(/\s+/);let n=0;document.querySelectorAll('.atlas-card').forEach(c=>{c.hidden=!words.every(w=>c.dataset.search.includes(w));if(!c.hidden)n++});s.textContent=n+' illustrated sections shown'});document.querySelectorAll('.chips a').forEach(a=>a.addEventListener('click',()=>{q.value='';q.dispatchEvent(new Event('input'))}))})();</script>'''
write(R/'parts-atlas.html',shell('Know the machine.<br>Name the part.','A visual parts atlas for paving, milling, compaction and supporting equipment.',body,nav,js))
with (R/'component-register.csv').open('w',newline='') as out:
 w=csv.writer(out,lineterminator='\n');w.writerow(['figure','document','original_pdf_page','callout','component','plain_language_function','model_scope','local_source_link']);w.writerows(rows)
# Independent activities and answer guidance. All fictional records are explicitly marked.
activities=[
('CAT-ID-01','Follow the material','Reading · Communication','Open Figures 1–3 and 5. Name the paver’s two main sections. Identify the feeder chain, auger shaft and screed plate. Explain to a partner how the feeder and augers have different roles. Have the listener point to each named part.','Tractor and screed. The feeder chain carries material through the feeder path; the augers distribute it across the width. Use the original leader lines, not the nearest-looking feature. The screed plate is the lower working surface that shapes the mat.'),
('CAT-ID-02','Read every conveyor callout','Reading · Writing','In Figure 12, list names for callouts 1–7. Then write a two-sentence identification note for callout 5: assembly, component, source publication and PDF page.','1 guide rollers; 2 trough rollers; 3 return idlers; 4 tail pulley; 5 tail pulley bearings; 6 bunk rollers; 7 head pulley. Example: “The component is the tail pulley bearings in the cold-planer conveyor diagram. CAT-08, Cold Planer Parts Reference Guide, PDF page 25, callout 5.”'),
('CAT-ID-03','Count callouts without inventing quantities','Numeracy · Problem solving','Figure 12 has 7 callout numbers. Figure 13 has 6. How many distinct callout numbers are listed across the two legends? If two identical classroom posters show Figure 12, how many numbered labels appear across those two posters? Explain why neither calculation tells you how many replacement parts to order.','7 + 6 = 13 legend entries across the diagrams. 2 × 7 = 14 printed labels on two posters. A callout may identify a type of part, several instances or an assembly. Required quantity and part number come from the applicable parts table and machine identity.'),
('CAT-ID-04','Check a roller-control match','Reading · Problem solving','Figure 14 identifies controls on the CB2.5 GC, CB2.7 GC and CC2.7 GC manual’s stated serial ranges. Locate 6, 12, 14 and 16. A fictional worksheet calls number 12 “engine start.” Correct it using the diagram.','6 emergency stop knob; 12 parking brake; 14 water spray system; 16 vibratory mode / emulsion switch. Engine start switch is 15, not 12. Retain optional equipment and model conditions. This is a diagram check, not an instruction to operate the controls.'),
('CAT-ID-05','Follow the loader letters','Reading · Communication','Use Figure 17. Find A, K, Y, S1 and S2. Describe the two connection points named for each pin. Ask a partner to repeat the difference between S1 and S2.','A loader arm to front frame; K lift cylinder to loader arm; Y lift cylinder to front frame; S1 steering cylinder to rear frame; S2 steering cylinder to front frame. A complete check-back preserves front/rear and the cylinder name.'),
('CAT-ID-06','Save a source you can find again','Digital · Writing','Search the CAT library for “tail pulley”. Open the hit from CAT-08 PDF page 25. Save a note containing publication, revision, original PDF page, part filename and local viewer page. Close the note, reopen it and use it to return to the same diagram.','CAT-08, QEXQ3131-01 (05/2026), original PDF page 25, sources/cold-planer-parts-official/p0001-0025.pdf, viewer page 25. Accept the actual generated path from the link if the collection is reorganized. Observe save/reopen/retrieval; a written promise to save is not evidence of the Digital action.'),
('CAT-ID-07','Respond to a changed machine record','Adaptability · Problem solving','Fictional record A says: “950M, prefix EMB, automatic standard lift.” Record B corrects it to: “950M, prefix KSA, standard lift; complete serial number not supplied.” Open CAT-17 PDF page 6. Mark which table row changes, what information you must still obtain, and why the model name alone is insufficient.','Move from EMB to KSA and the stated lift configuration. Obtain the complete serial/product identification number and verify the current applicable parts catalogue and arrangement. Prefix and lift type affect the table lookup. Keep the original and corrected record; do not issue a part order from this exercise.'),
('CAT-ID-08','Make a component check-back','Communication · Collaboration','In pairs, choose a cutting-chamber part in Figure 10. One person gives its callout, exact name, location and source. The other finds it and restates the identification. Swap roles using a different part. Each person records one correction or confirmation.','Accept callouts 1–4 with exact source names and correct diagram location. Observe both contributions and an actual check-back. If the listener identifies the wrong ski or edge, return to the leader line and repair the message together.'),
('CAT-ID-09','Design a useful learning card','Creativity and innovation · Digital','Create two layouts for a learning card containing one credited diagram, a part name, plain-language function and model scope. Ask another reader to find the named part without help. Record what happened, choose a layout, revise it and save the final file.','Keep both ideas, the reader’s task result and the explained revision. A useful card has a readable callout, source/page credit, accurate scope and no obscured labels. Do not redraw a WHMIS symbol or replace a manufacturer warning with invented artwork.'),
('CAT-ID-10','Complete a machine identification record','Reading · Writing · Collaboration','Use a supplied training machine record or one of the manuals in the library. Record model, serial applicability, attachment, publication number/revision, assembly, page and callout. Mark unknown fields “to confirm”. A second person checks the source match and signs or initials the classroom record.','A complete record distinguishes what is stated in the manual from what is known about the actual machine. Unknown identity fields remain explicit. The reviewer verifies the same source and records the result. No learner needs to share personal information or enter an operating area to complete this classroom task.')]
write(R/'activities.json',json.dumps([dict(id=a,title=b,skills=c,task=d,answer=e) for a,b,c,d,e in activities],ensure_ascii=False,indent=2)+'\n')
intro='<section class="panel"><h2>Find it, explain it, check it</h2><p>Work from the atlas and the original PDF pages. Use a separate notebook, typed document or the spaces on a printed copy. A partner may read a prompt aloud; each learner keeps their own answer and source record.</p><p class="callout">These are classroom identification tasks. Actual machine walkarounds, access, isolation and operation require the applicable manual, site procedures and qualified supervision.</p><p>Suggested route: tasks 1–5 for diagram reading, 6–7 for document control, 8–10 for checked communication and a reusable identification record. All nine Skills for Success produce observable work across the sequence.</p></section>'
for j in range(0,len(activities),3):
 intro+='<section class="panel"><h2>Identification practice</h2>'+''.join(f'<article class="exercise" id="{a}"><p class="skills">{a} · {c}</p><h3>{b}</h3><p>{d}</p><div class="answer-space"></div></article>' for a,b,c,d,e in activities[j:j+3])+'</section>'
write(R/'practice.html',shell('Find the part.<br>Explain the evidence.','Ten complete identification tasks using the CAT parts atlas.',intro,'<a href="parts-atlas.html">Parts atlas</a><a href="practice.pdf">Print practice</a><a href="teaching-guide.html">Answer guidance</a>'))
answers='<section class="panel"><h2>Teach the source check</h2><p>Model one callout: show the leader line, read the exact term, explain its purpose and name the publication/page. Then ask the learner to do the next example. Accept pointing, speech or accessible text for identification, and collect writing or digital work when those skills are being assessed.</p><p>Record: accurate name; correct callout; correct source/model scope; explanation of uncertainty; successful check-back. Give feedback and another attempt. These classroom records do not certify equipment operation or complete a technical trade competency.</p></section>'
for j in range(0,len(activities),3):answers+='<section class="panel"><h2>Answer and observation guidance</h2>'+''.join(f'<article class="exercise"><p class="skills">{a}</p><h3>{b}</h3><p>{e}</p></article>' for a,b,c,d,e in activities[j:j+3])+'</section>'
answers+='<section class="panel"><h2>Nine Skills for Success: evidence to keep</h2><table class="simple"><thead><tr><th>Skill</th><th>Evidence in these tasks</th></tr></thead><tbody>'+''.join(f'<tr><td>{a}</td><td>{b}</td></tr>' for a,b in [('Reading','Matched callout, table heading and model scope: 01, 02, 04, 05, 07, 10.'),('Writing','Authored identification note and corrected machine record: 02, 06, 10.'),('Numeracy','Two checked counts and the limit of the result: 03.'),('Digital','Observed search, file save, reopen and source retrieval: 06, 09.'),('Problem solving','Detected mismatch, evidence check and unresolved information: 03, 04, 07.'),('Communication','Exact term, location and listener check-back: 01, 05, 08.'),('Collaboration','Two contributions, shared source check and recorded correction: 08, 10.'),('Adaptability','First and revised record after the supplied change: 07.'),('Creativity and innovation','Two proposed cards, reader trial and explained revision: 09.')])+'</tbody></table></section>'
write(R/'teaching-guide.html',shell('Teach identification.<br>Check understanding.','Answers, feedback and nine-skills evidence for CAT-ID-01–10.',answers,'<a href="practice.html">Learner practice</a><a href="teaching-guide.pdf">Print teaching guide</a><a href="parts-atlas.html">Parts atlas</a>'))
# Manufacturer warning pages: preserve complete warnings and context.
warnings=[]
for n in [9,10]:
 src=R/next(p['file'] for p in D['CAT-10']['parts'] if p['start']<=n<=p['end']);doc=fitz.open(src);page=doc[n-1];out=W/'assets'/f'cat-roller-safety-p{n:02d}.png';page.get_pixmap(dpi=160,alpha=False).save(out);warnings.append(dict(document='CAT-10',source_pdf_page=n,file=out.relative_to(W).as_posix(),sha256=hashlib.sha256(out.read_bytes()).hexdigest(),processing='Complete source page rendered at 160 dpi; no warning text cropped or altered.'));doc.close()
H['machine_warning_figures']=warnings;write(W/'manifest.json',json.dumps(H,ensure_ascii=False,indent=2)+'\n')
meanings={
'flame_circle':('Oxidizing hazards','Can cause or intensify fire. Read the actual product’s hazard and precautionary statements.'),
'flame':('Fire-related hazards','Used for specified flammable, self-reactive, pyrophoric, self-heating and other fire-related classes/categories. The exact hazard is stated on the label and SDS.'),
'exploding_bomb':('Explosion or violent reaction','Used in WHMIS for specified self-reactive substances and mixtures and organic peroxides. Read the classification and conditions; do not infer them from the picture alone.'),
'gas_cylinder':('Pressure hazards','Used for gases under pressure and chemicals under pressure. The product’s statements identify its particular pressure and related hazards.'),
'skull_crossbones':('Severe acute toxicity','Used for acute toxicity categories 1–3 by the applicable exposure route. Keep the label’s exact route and hazard statement.'),
'corrosion':('Corrosion or serious damage','May identify corrosive-to-metals, skin-corrosion or serious-eye-damage hazards. Read which hazards apply to the product.'),
'exclamation_mark':('Harmful or irritating effects','Used for specified acute toxicity, irritation, skin sensitization and other categories. It does not mean “minor” or “safe”.'),
'health_hazard':('Serious health effects','Used for specified hazards such as cancer, respiratory sensitization, reproductive toxicity, organ damage and aspiration. The symbol alone does not identify which one applies.'),
'biohazardous':('Biohazardous infectious materials','Used for biohazardous infectious materials. This Canadian WHMIS pictogram has a circular border, not the red diamond used for the other illustrated WHMIS pictograms.'),
'environment':('Hazardous to the aquatic environment','This GHS pictogram may appear on products, but environmental hazards are not part of the mandatory Canadian WHMIS hazard classes. Keep environmental precautions from the applicable SDS and site plan.')}
body='<div class="stats"><div class="stat"><strong>9 + 1</strong><span>WHMIS set + environment</span></div><div class="stat"><strong>3</strong><span>SVG · PNG · EPS formats</span></div><div class="stat"><strong>7</strong><span>Official source PDFs</span></div></div><section class="panel"><h2>Recognize the symbol.<br>Read the whole message.</h2><p>A pictogram alerts you to a type of hazard. The label and safety data sheet (SDS) explain the particular product and its precautions. The same work area can also have machine warnings, traffic signs and emergency signs; each has a different purpose.</p><p>In an asphalt crew, check the actual products used for the task: fuels, cleaners, release agents and other supplied materials. Do not assign a WHMIS classification from the word “asphalt”, a container colour or a familiar brand.</p><p class="callout">Some WHMIS hazard classes and categories have no required pictogram. No pictogram does not mean no hazard. Check the product identifier, complete label and SDS Section 2.</p><p>This classroom material develops WHMIS understanding. The employer also provides training for the actual hazardous products, tasks, controls and emergency procedures at the workplace.</p><p class="meta">Current teaching basis: CCOHS fact sheets revised 28 May 2026, reflecting the December 2022 HPR amendments. The two WorkSafeBC books in the source pack are labelled as 2019 historical explanations.</p></section><section class="panel"><h2>The pictogram library</h2><p>Official CCOHS artwork, retained in its standard form. SVG files are faithful vector conversions of the supplied EPS artwork. Frame, symbol and colours have not been redesigned.</p><div class="symbol-grid">'
for p in H['pictograms']:
 heading,meaning=meanings[p['id']];body+=f'<article class="symbol" id="{p["id"]}"><img src="{p["files"]["svg"]["path"]}" alt="{E(p["name"],quote=True)} pictogram" width="112" height="112"><div><h3>{E(p["name"])}</h3><p><strong>{heading}.</strong> {meaning}</p><p class="links">'+ ' · '.join(f'<a href="{p["files"][fmt]["path"]}">{fmt.upper()}</a>' for fmt in ['svg','png','eps'])+'</p></div></article>'
body+='</div><p class="credit">Canadian Centre for Occupational Health and Safety. (n.d.). <em>WHMIS pictograms</em> [Pictogram kit]. <a href="https://www.ccohs.ca/WHMISpictograms.html">Official download page</a>. Accessed 30 October 2026. Meanings above are concise teaching descriptions; the <a href="sources/ccohs-pictograms.pdf">2026 pictograms fact sheet</a> gives the classes and categories.</p></section>'
body+='<section class="panel"><h2>Three sources of information</h2><ol class="steps"><li><strong>Identify</strong><br>Match the product name on container, label and SDS.</li><li><strong>Read</strong><br>Read hazard statements and precautions, not just the pictogram.</li><li><strong>Locate</strong><br>Find task-specific information in the SDS and workplace procedures.</li><li><strong>Check</strong><br>Resolve missing or conflicting information with the designated person before the task.</li></ol><h3>Supplier label</h3><p>Look for the product identifier, initial supplier identifier, applicable pictograms, signal word, hazard statements and precautionary statements. Required supplemental information may also apply. Supplier label information is provided in English and French. “Danger” and “Warning” are signal words; their use depends on classification.</p><h3>Workplace label</h3><p>A workplace label generally contains the product identifier matching the SDS, safe-handling information and a statement that the SDS is available. Requirements and limited exceptions for transferred containers depend on the circumstances and jurisdiction. Use the employer’s procedure; do not treat “only a small amount” as a reason to leave a shared container unidentified.</p></section><section class="panel"><h2>Find the information in an SDS</h2><p>An SDS has 16 section headings. Read the current SDS for the exact product. A similar name, an old screenshot or a different supplier’s sheet is not a confirmed match.</p><div class="tablewrap"><table class="simple"><thead><tr><th>Question</th><th>Start here</th><th>Keep checking</th></tr></thead><tbody><tr><td>Which product and supplier?</td><td>1 · Identification</td><td>Label and actual container</td></tr><tr><td>Which hazards and label elements?</td><td>2 · Hazard identification</td><td>Full statements and classification</td></tr><tr><td>What is in it?</td><td>3 · Composition/information on ingredients</td><td>Applicable disclosure information</td></tr><tr><td>First aid, fire or spill?</td><td>4 · First-aid measures; 5 · Fire-fighting measures; 6 · Accidental release measures</td><td>Workplace emergency procedure and trained response</td></tr><tr><td>Handling, storage and exposure controls?</td><td>7 · Handling and storage; 8 · Exposure controls/personal protection</td><td>Task, exposure and workplace controls</td></tr><tr><td>Properties, reactions and health effects?</td><td>9 · Physical/chemical properties; 10 · Stability/reactivity; 11 · Toxicological information</td><td>Conditions, routes and limits</td></tr><tr><td>Environment, disposal, transport and rules?</td><td>12 · Ecological; 13 · Disposal; 14 · Transport; 15 · Regulatory information</td><td>Headings are required; these sections’ content is not mandatory under the HPR. Other requirements can apply.</td></tr><tr><td>When was the SDS prepared or revised?</td><td>16 · Other information</td><td>Revision and supplier updates</td></tr></tbody></table></div><p class="credit">Teaching summary from CCOHS (2026), <a href="sources/ccohs-labels.pdf"><em>WHMIS—Labels</em></a> and <a href="sources/ccohs-sds.pdf"><em>WHMIS—Safety Data Sheet (SDS)</em></a>. Consult the complete sheets for conditions and exceptions.</p></section>'
body+='<section class="panel"><h2>Machine warnings have their own context</h2><p>The pages below show genuine CAT roller safety messages. Hot-surface and crush warnings describe equipment hazards. A chemical pictogram on a product label describes that product’s classification. Keep the message with its location, machine and complete instruction.</p><table class="simple"><thead><tr><th>Example</th><th>Where to look</th><th>What to preserve</th></tr></thead><tbody><tr><td>Hot surface</td><td>CAT-10, PDF page 9, safety message 4</td><td>Location near exhaust outlet, illustration and full burn warning</td></tr><tr><td>Crush hazard</td><td>CAT-10, PDF page 10, messages 5 and 6</td><td>Articulation location, machine movement and frame-lock context</td></tr><tr><td>ROPS warning</td><td>CAT-10, PDF page 10, message 7</td><td>Complete do-not-weld-or-drill warning and model context</td></tr></tbody></table><p class="callout">Use the exact machine’s warning labels and manual during supervised training. The reproduced pages are from M0130633-02 for its listed CB2.5 GC, CB2.7 GC and CC2.7 GC serial ranges. These images are classroom references, not replacement machine decals.</p></section>'
for n in [9,10]:body+=f'<section class="panel"><h2>CAT roller warnings · source page {n}</h2><a href="assets/cat-roller-safety-p{n:02d}.png"><img class="machine-page" src="assets/cat-roller-safety-p{n:02d}.png" alt="Complete CAT roller safety page {n}; full-size image and accessible source PDF follow"></a><p class="credit">{credit("CAT-10",n,"../caterpillar/")} This reproduction retains the complete page.</p></section>'
body+='<section class="panel" id="sources"><h2>Source shelf</h2><p>The five CCOHS sheets below are the current teaching sources in this dated collection. The WorkSafeBC books remain useful B.C. background, with their 2019 editions visible.</p><ul>'+''.join(f'<li>{E(d["publisher"])}. ({d["year"]}). <a href="{d["file"]}"><em>{E(d["title"])}</em></a>. {d["pages"]} pages. {E(d["role"])} <a href="{E(d["source_url"],quote=True)}">Original download</a>.</li>' for d in H['documents'])+'</ul><p><a href="sources/ccohs-official-pictograms.zip">Unchanged official CCOHS pictogram ZIP</a> · <a href="manifest.json">Source hashes and conversion record</a> · <a href="https://www.worksafebc.com/en/law-policy/occupational-health-safety/searchable-ohs-regulation/ohs-regulation/part-05-chemical-and-biological-substances">Current WorkSafeBC Part 5 requirements</a></p></section>'
write(W/'index.html',shell('Read the hazard.<br>Protect the crew.','WHMIS pictograms, machine warnings and the documents that explain them.',body,'<a href="whmis-reference.pdf">Print reference</a><a href="practice.html">WHMIS practice</a><a href="whmis-classroom-pack.zip">Download ZIP</a><a href="../caterpillar/parts-atlas.html">Machine parts atlas</a>'))
whacts=[('WH-01','Name the message','Reading · Communication','Find the flame, flame over circle, corrosion and gas cylinder. Explain one difference between the flame and flame over circle. Then locate the hot-surface warning in the CAT page. Which belongs to a machine warning system rather than a product classification?','Flame concerns specified fire-related hazards; flame over circle identifies oxidizers. Hot surface on the CAT safety page is a machine warning. Exact chemical hazards come from the actual label and SDS.'),('WH-02','Match the right document','Reading · Problem solving','Fictional desk records: container label = “Crew Clean A”, supplier = “North Training Supply”; SDS 1 = “Crew Clean B”, same supplier; SDS 2 = “Crew Clean A”, supplier = “West Training Supply”. Neither sheet has been checked against the container. Which sheet is confirmed? What information would you seek before the task?','Neither is confirmed. Obtain the current SDS for the exact product and supplier, compare product identifiers and label information, and resolve any distributor/supplier naming relationship with the responsible person. Do not choose by similar title.'),('WH-03','Find the section','Reading · Digital','Open the CCOHS SDS sheet. Record which SDS sections address first aid, accidental release, handling/storage, exposure controls/PPE and revision information. Save your answers with the source URL and revision date; close and reopen the file.','Sections 4, 6, 7, 8 and 16 respectively. Source: CCOHS WHMIS—Safety Data Sheet (SDS), revised 28 May 2026. Observe the digital save/reopen action.'),('WH-04','Keep a count and report a gap','Numeracy · Writing','Fictional classroom audit: 12 labelled sample cards are supplied. Nine cards have a matching practice SDS; two have the wrong product name; one has no SDS. How many lack a confirmed match? What percentage is that? Write a brief note describing the gap without inventing a product hazard.','2 + 1 = 3 cards. 3 ÷ 12 × 100 = 25%. Example: “Three of twelve classroom cards lack a confirmed SDS match: two names differ and one sheet is missing. Obtain and verify the correct sheets before using these as product-specific examples.”'),('WH-05','No symbol is not no hazard','Problem solving · Communication','A fictional learner says, “There is no diamond, so we can use it.” Use the pictograms sheet to check that statement. Explain your correction to a partner and ask for a check-back.','Some hazard classes/categories require no pictogram. Read the complete label and SDS Section 2 and follow workplace training. The biohazardous infectious materials pictogram also uses a circular border. A partner should restate the need to check the full information.'),('WH-06','Update a shared briefing','Adaptability · Collaboration · Creativity and innovation','Fictional change: the supervisor replaces a practice SDS with a newly verified revision. In pairs, design two ways to make the revision visible on a briefing card. Choose one, test whether another reader can find the date and exact product, revise it and record both contributions. Keep official pictograms unchanged.','Retain both design options, the changed revision record, a reader trial and explained improvement. Each learner contributes and checks the new product/date against the supplied revised document. The exercise does not imply every SDS revision changes the hazard classification.')]
write(W/'activities.json',json.dumps([dict(id=a,title=b,skills=c,task=d,answer=e) for a,b,c,d,e in whacts],ensure_ascii=False,indent=2)+'\n')
