 for j in range(0,len(whacts),3):body+='<section class="panel"><h2>'+('Answer guidance' if answers_mode else 'WHMIS practice')+'</h2>'+''.join(f'<article class="exercise"><p class="skills">{a} · {c}</p><h3>{b}</h3><p>{e if answers_mode else d}</p></article>' for a,b,c,d,e in whacts[j:j+3])+'</section>'
 title='Check the hazard reading.' if answers_mode else 'Find the symbol.<br>Check the document.';file='teaching-guide' if answers_mode else 'practice'
